    \coordinate[label=below:{$I$}] (H) at (intersection of B--D and E--C); 
    \coordinate[label=above right:{$N$}] (I) at ($(A)!0.5!(H)$);
    \draw (0,0) circle[radius=2cm] (A)--(B)--(C)--(D)--(A)--(H) (B)--(D)--(E) (C)--(E)--(I)--(D);
